INSERT INTO workout_activities (id,name,category,definition) VALUES ('a1','Goblet Squat','strength','{"id":"a1","name":"Goblet Squat","category":"strength","focus":"quadriceps, glutes","equipment":"dumbbell","movement":"squat","tracking":"load","instructions":"Hold one dumbbell vertically at your chest. Feet shoulder-width, sit hips back and down, chest tall. Knees track over toes. Barbell option: front squat or back squat with the bar racked — same tempo, same rep range, don''t chase heavy weight here.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a2','Dumbbell Row (bent over)','strength','{"id":"a2","name":"Dumbbell Row (bent over)","category":"strength","focus":"back, biceps","equipment":"dumbbell","movement":"pull","tracking":"load","instructions":"Hinge at the hips, flat back, one dumbbell hanging. Pull elbow back past your ribs, squeeze the shoulder blade. Barbell option: barbell bent-over row, both arms together, same hinge position — good for hitting your back a bit harder.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a3','Push-up (knees if needed)','strength','{"id":"a3","name":"Push-up (knees if needed)","category":"strength","focus":"chest, triceps","equipment":"bodyweight","movement":"push","tracking":"reps","instructions":"Hands under shoulders, body in a straight line. Drop knees to the floor if a full push-up is too hard. This is your main chest builder — form matters more than the version.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a4','Dumbbell Shoulder Press','strength','{"id":"a4","name":"Dumbbell Shoulder Press","category":"strength","focus":"shoulders, triceps","equipment":"dumbbells","movement":"push","tracking":"load","instructions":"Seated or standing, press dumbbells overhead without arching your lower back. Barbell option: standing barbell overhead press — brace your core hard, press straight up past your face.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a5','Romanian Deadlift','strength','{"id":"a5","name":"Romanian Deadlift","category":"strength","focus":"hamstrings, glutes","equipment":"dumbbells","movement":"hinge","tracking":"load","instructions":"Soft knees, hinge at the hips and slide dumbbells down your thighs, back flat. Barbell option: same hinge, bar stays close to your legs the whole way down — this is where a barbell really helps since you can load it more than dumbbells.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a6','Plank','strength','{"id":"a6","name":"Plank","category":"strength","focus":"core","equipment":"bodyweight","movement":"brace","tracking":"hold","instructions":"Forearms down, straight line from head to heels. Squeeze glutes and abs — don''t let hips sag or pike up.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a7','Bicycle Crunch','strength','{"id":"a7","name":"Bicycle Crunch","category":"strength","focus":"core","equipment":"bodyweight","movement":"rotation","tracking":"reps","instructions":"Core finisher. Hands behind head, opposite elbow to opposite knee, slow and controlled — don''t yank your neck. This targets the obliques and lower abs for tone.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('a8','Lying Leg Raise','strength','{"id":"a8","name":"Lying Leg Raise","category":"strength","focus":"core, hip flexors","equipment":"bodyweight","movement":"brace","tracking":"reps","instructions":"Core finisher. Lie flat, legs straight, lower back pressed into the floor. Raise legs to 90°, lower slowly without arching your back. Bend knees slightly if your lower back complains.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b1','Reverse Lunge (dumbbells)','strength','{"id":"b1","name":"Reverse Lunge (dumbbells)","category":"strength","focus":"quadriceps, glutes","equipment":"dumbbells","movement":"lunge","tracking":"load","instructions":"Dumbbells at your sides, step back and lower until both knees hit ~90°. Push through the front heel to return.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b2','Dumbbell Deadlift','strength','{"id":"b2","name":"Dumbbell Deadlift","category":"strength","focus":"glutes, hamstrings","equipment":"dumbbells","movement":"hinge","tracking":"load","instructions":"Dumbbells in front of thighs, hinge down keeping them close to your legs, flat back throughout. Barbell option: conventional barbell deadlift — bar stays over mid-foot, drive through your heels to stand.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b3','Incline Press (DB or Barbell)','strength','{"id":"b3","name":"Incline Press (DB or Barbell)","category":"strength","focus":"chest, triceps","equipment":"dumbbells, bench","movement":"push","tracking":"load","instructions":"Incline push-up: hands on a sturdy elevated surface. Or lie on an incline bench/pillow wedge and press dumbbells or a barbell up and slightly back — this angle hits the upper chest more than a flat press, good for chest tone.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b4','Lateral Raise','strength','{"id":"b4","name":"Lateral Raise","category":"strength","focus":"shoulders","equipment":"dumbbells","movement":"raise","tracking":"load","instructions":"Light weight (2–3kg is plenty). Raise arms out to the sides to shoulder height, slight bend in elbows. Control the lowering — that''s where most of the work happens. This is the move that gives shoulders that rounded, toned look.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b5','Bicep Curl','strength','{"id":"b5","name":"Bicep Curl","category":"strength","focus":"biceps","equipment":"dumbbells","movement":"curl","tracking":"load","instructions":"Dumbbell or barbell, elbows pinned to your sides, curl up without swinging your body. Barbell lets both arms work together evenly — good for building visible bicep tone without needing heavy weight.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b6','Bird-dog','strength','{"id":"b6","name":"Bird-dog","category":"strength","focus":"core, glutes","equipment":"bodyweight","movement":"brace","tracking":"reps","instructions":"On hands and knees, extend opposite arm and leg straight out, hold briefly. Keep hips level — don''t let your torso rotate.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b7','Weighted Russian Twist','strength','{"id":"b7","name":"Weighted Russian Twist","category":"strength","focus":"core","equipment":"dumbbell","movement":"rotation","tracking":"load","instructions":"Core finisher. Sit with knees bent, lean back slightly, hold one dumbbell or a plate with both hands. Rotate side to side, tapping the weight near the floor. Keep the movement controlled, not fast.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
INSERT INTO workout_activities (id,name,category,definition) VALUES ('b8','Mountain Climbers','strength','{"id":"b8","name":"Mountain Climbers","category":"strength","focus":"core, conditioning","equipment":"bodyweight","movement":"brace","tracking":"hold","instructions":"Core finisher. Plank position, drive knees toward your chest alternating quickly but with control. Keep hips low — this also adds a light cardio hit.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load."}') ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),definition=VALUES(definition);
