INSERT INTO workout_templates (id,name,definition) VALUES ('strength-a','Strength A','{"id":"strength-a","name":"Strength A","style":"straight","items":[{"activityId":"a1","target":"3 × 12–15","setCount":3},{"activityId":"a2","target":"3 × 12–15 per side","setCount":3},{"activityId":"a3","target":"3 × 10–15","setCount":3},{"activityId":"a4","target":"3 × 12–15","setCount":3},{"activityId":"a5","target":"3 × 12–15","setCount":3},{"activityId":"a6","target":"3 × 30–45 sec","setCount":3},{"activityId":"a7","target":"3 × 20 (10 per side)","setCount":3},{"activityId":"a8","target":"3 × 12–15","setCount":3}]}') ON DUPLICATE KEY UPDATE name=VALUES(name),definition=VALUES(definition);
INSERT INTO workout_templates (id,name,definition) VALUES ('strength-b','Strength B','{"id":"strength-b","name":"Strength B","style":"straight","items":[{"activityId":"b1","target":"3 × 10–12 per side","setCount":3},{"activityId":"b2","target":"3 × 12–15","setCount":3},{"activityId":"b3","target":"3 × 12–15","setCount":3},{"activityId":"b4","target":"3 × 12–15","setCount":3},{"activityId":"b5","target":"3 × 12–15","setCount":3},{"activityId":"b6","target":"3 × 10 per side","setCount":3},{"activityId":"b7","target":"3 × 16 (8 per side)","setCount":3},{"activityId":"b8","target":"3 × 30 sec","setCount":3}]}') ON DUPLICATE KEY UPDATE name=VALUES(name),definition=VALUES(definition);
